    flags={'-a':'all','--all':'all','-b':'bundle','--bundle':'bundle','-i':'inplace','--inplace':'inplace','-l':'list','--list':'list','-q':'quiet','--quiet':'quiet','-r':'recursive','--recursive':'recursive','-s':'sync','--sync':'sync','-w':'watch','--watch':'watch','-h':'help','--help':'help','-v':'verbose','--version':'version','--html-keep-comments':'html_comments','--html-keep-conditional-comments':'html_cond','--html-keep-default-attrvals':'html_defaults','--html-keep-document-tags':'html_doc','--html-keep-end-tags':'html_end','--html-keep-quotes':'html_quotes','--html-keep-special-comments':'html_special','--html-keep-whitespace':'html_ws','--js-keep-var-names':'js_keep','--json-keep-numbers':'json_keep','--svg-keep-comments':'svg_comments','--xml-keep-whitespace':'xml_ws'}
    takes={'-o':'output','--output':'output','--type':'type','--mime':'mime','--url':'url','-v':'verbose','--verbose':'verbose','--css-precision':'css_precision','--css-version':'css_version','--js-precision':'js_precision','--js-version':'js_version','--json-precision':'json_precision','--svg-precision':'svg_precision','--svg-keep-namespaces':'svg_ns','-p':'preserve','--preserve':'preserve','--match':'match','--include':'include','--exclude':'exclude','--ext':'ext'}
    while i<len(argv):
        a=argv[i]
        if a=='--': inputs.extend(argv[i+1:]); break
        if a in flags:
            key=flags[a]
            if key=='verbose': opts[key]=opts.get(key,0)+1
            else: opts[key]=True
        elif a in takes:
            key=takes[a]; opts.setdefault(key,[])
            i+=1
            if i>=len(argv): error('option requires an argument: '+a,2)
            opts[key].append(argv[i])
        elif a.startswith('--ext.') and '=' in a:
            extension, filetype=a[len('--ext.'):].split('=',1)
            opts.setdefault('ext',[]).append(extension+'='+filetype)
        elif a.startswith('--') and '=' in a:
            k,v=a.split('=',1)
            if k in takes: opts.setdefault(takes[k],[]).append(v)
            elif k.startswith('--ext.'):
                opts.setdefault('ext',[]).append(k[len('--ext.'): ]+'='+v)
            elif k in flags:
                key=flags[k]
                val=(v.lower() not in ('false','0','no'))
                if key=='verbose': opts[key]=opts.get(key,0)+(int(v) if v.isdigit() else int(val))
                else: opts[key]=val
            else: bad_option('unknown option '+k)
        elif a.startswith('-') and len(a)>2 and a[1] != '-':
            chars=a[1:]
            for pos,ch in enumerate(chars):
                k='-'+ch
                if k in flags:
                    key=flags[k]
                    if key=='verbose': opts[key]=opts.get(key,0)+1
                    else: opts[key]=True
                elif k in takes:
                    rest=chars[pos+1:]
                    if rest: val=rest
                    else:
                        i+=1
                        if i>=len(argv): error('option requires an argument: '+k,2)
                        val=argv[i]
                    opts.setdefault(takes[k],[]).append(val)
                    break
                else: bad_option('unknown option '+k)
        elif a.startswith('-'): bad_option('unknown option '+a)
        else: inputs.append(a)
        i+=1
    return opts,inputs

def list_types():
    for k,v in EXTS.items(): print(f'{k:<12} {v}')

def pattern_matches(pattern, value):
    try:
        if pattern.startswith('~'): return re.search(pattern[1:],value) is not None
        rx=''; i=0
        while i<len(pattern):
            c=pattern[i]
            if c=='\\' and i+1<len(pattern):
                i+=1; rx+=re.escape(pattern[i])
            elif c=='*':
                if i+1<len(pattern) and pattern[i+1]=='*': rx+='.*'; i+=1
                else: rx+='[^/]*'
            elif c=='?': rx+='[^/]'
            elif c=='[':
                j=pattern.find(']',i+1)
                if j>=0: rx+=pattern[i:j+1]; i=j
                else: rx+='\\['
            else: rx+=re.escape(c)
            i+=1
        return re.fullmatch(rx,value) is not None
    except re.error: return False

